skin:
#s97 .stage{background:#f2e9d8;color:#1b2a6b;background-image:radial-gradient(#ff48b026 1px,transparent 1.6px);background-size:7px 7px}
#s97 .d-nav{background:#fffaf0;border:2px solid #1b2a6b;border-radius:0;box-shadow:3px 3px 0 #ff48b0}
#s97 .d-logo{font-weight:900;text-transform:uppercase;letter-spacing:.06em;color:#1b2a6b;text-shadow:2px 2px 0 #ff48b04d}
#s97 .d-links span{text-transform:uppercase;font-weight:700;color:#0078bf}#s97 .d-links span:hover{color:#ff48b0}
#s97 .d-h{font-weight:900;text-transform:uppercase;letter-spacing:.02em}
#s97 .d-p{color:#2b2118}
#s97 .d-btn{background:#ff48b0;color:#fffaf0;border:2px solid #1b2a6b;border-radius:0;box-shadow:3px 3px 0 #1b2a6b;font-weight:800;text-transform:uppercase;letter-spacing:.05em}
#s97 .d-btn:hover{transform:translate(-1px,-1px);box-shadow:4px 4px 0 #1b2a6b}
#s97 .d-btn.ghost{background:#0078bf;color:#fffaf0}
#s97 .d-input{background:#fffaf0;border:2px dashed #1b2a6b;border-radius:0}
#s97 .d-badge{background:#1b2a6b;color:#ffd9ef;border-radius:0;font-weight:800;letter-spacing:.04em}
#s97 .d-prog{background:#fffaf0;border:2px solid #1b2a6b;border-radius:0}#s97 .d-prog i{background:#ff48b0}
#s97 .d-card{background:#fffaf0;border:2px solid #1b2a6b;border-radius:0;box-shadow:5px 5px 0 #ff48b066;transform:rotate(-.4deg)}
